function v3(a){return new THREE.Vector3(a[0],a[1],a[2]);}
function bone(name,a,b,r=.035,color=0xc9d7df){const A=v3(a),B=v3(b),d=new THREE.Vector3().subVectors(B,A),len=d.length();const m=new THREE.Mesh(new THREE.CylinderGeometry(r*.72,r,len,10,1),new THREE.MeshStandardMaterial({color,roughness:.62,metalness:.12}));m.position.copy(A).add(B).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());m.userData={name};bodyRoot.add(m);pickables.push(m);return m;}
