function onTwinPick(e){const r=$('twin3d').getBoundingClientRect();mouse.x=((e.clientX-r.left)/r.width)*2-1;mouse.y=-((e.clientY-r.top)/r.height)*2+1;raycaster.setFromCamera(mouse,camera);const hits=raycaster.intersectObjects(pickables,false);if(!hits.length)return;const m=hits[0].object;const name=m.userData.name||'Bone';const info=boneInfo[name]||[name,'Joint / skeletal landmark represented in the reference model.'];$('boneTitle').textContent=info[0];$('boneDesc').textContent=info[1];$('boneRegion').textContent=name.toUpperCase();$('boneFunction').textContent=info[1];if(selectedMesh&&selectedMesh.material.emissive)selectedMesh.material.emissive.setHex(0x000000);selectedMesh=m;if(m.material.emissive)m.material.emissive.setHex(0x087b9b);log('TWIN_PICK',name);}
