// ---------- 12-feature in-browser Isolation Forest ----------
const features=['heart_rate','bp_systolic','glucose_mg_dl','temperature_c','sleep_hours','mood_stress','exercise_min','radiation_msv_day','urine_calcium_mg_day','hydration_l_day','eye_tracking_pct','cognitive_reaction_ms'];
let forest=null,trainingRows=[],lastInference=null,lastVitalAssessment=null,alertsAcknowledged=false;
function randn(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function clamp(x,a,b){return Math.max(a,Math.min(b,x))}
function synthRow(){return [70+randn()*7,118+randn()*9,95+randn()*10,36.8+randn()*.22,7.4+randn()*.65,3+randn()*1.25,45+randn()*15,.35+randn()*.12,180+randn()*50,2.2+randn()*.3,92+randn()*4,280+randn()*32].map((v,i)=>clamp(v,[35,75,55,35.5,3,0,0,0,20,.5,50,120][i],[120,160,180,38.2,10,8,120,1.2,350,4,100,500][i]));}
function cFactor(n){if(n<=1)return 0;if(n===2)return 1;const H=Math.log(n-1)+.5772156649;return 2*H-2*(n-1)/n;}
function pathLength(x,node,depth=0){if(node.leaf)return depth+node.sizeCorrection;return x[node.feature]<node.split?pathLength(x,node.left,depth+1):pathLength(x,node.right,depth+1)}
function buildTree(rows,depth,maxDepth){if(depth>=maxDepth||rows.length<=1)return {leaf:true,sizeCorrection:cFactor(rows.length)};const d=rows[0].length,mins=Array(d).fill(Infinity),maxs=Array(d).fill(-Infinity);for(const r of rows)for(let j=0;j<d;j++){mins[j]=Math.min(mins[j],r[j]);maxs[j]=Math.max(maxs[j],r[j]);}const choices=[];for(let j=0;j<d;j++)if(maxs[j]-mins[j]>1e-9)choices.push(j);if(!choices.length)return {leaf:true,sizeCorrection:cFactor(rows.length)};const f=choices[Math.floor(Math.random()*choices.length)],split=mins[f]+Math.random()*(maxs[f]-mins[f]),left=[],right=[];for(const r of rows)(r[f]<split?left:right).push(r);if(!left.length||!right.length)return {leaf:true,sizeCorrection:cFactor(rows.length)};return {leaf:false,feature:f,split,left:buildTree(left,depth+1,maxDepth),right:buildTree(right,depth+1,maxDepth)};}
function modelStats(rows){const means=features.map((_,j)=>rows.reduce((s,r)=>s+r[j],0)/rows.length),stds=features.map((_,j)=>Math.sqrt(rows.reduce((s,r)=>s+(r[j]-means[j])**2,0)/rows.length)||1);return {means,stds};}
function rawScore(row,model){const avg=model.trees.reduce((s,t)=>s+pathLength(row,t,0),0)/model.trees.length;return Math.pow(2,-avg/cFactor(model.sampleSize));}
function scoreRow(row,model=forest){if(!model||!model.trees.length)throw Error('AI model is not trained.');const score=rawScore(row,model),contributions=row.map((v,j)=>Math.abs((v-model.means[j])/model.stds[j]));return {score,contributions,means:model.means,stds:model.stds};}
function buildForest(rows,nTrees=100){const sampleSize=Math.min(128,rows.length),maxDepth=Math.ceil(Math.log2(sampleSize)),trees=[];for(let t=0;t<nTrees;t++){const sample=[];for(let i=0;i<sampleSize;i++)sample.push(rows[Math.floor(Math.random()*rows.length)]);trees.push(buildTree(sample,0,maxDepth));}return {trees,sampleSize,rows:rows.length};}
function fitForest(rows){if(rows.length<50)throw Error('At least 50 valid baseline rows are required.');const shuffled=[...rows].sort(()=>Math.random()-.5),cut=Math.max(30,Math.floor(shuffled.length*.8));if(rows.length-cut<10)throw Error('Add more baseline rows for held-out validation (at least 60 total).');const train=shuffled.slice(0,cut),valid=shuffled.slice(cut),validationModel=buildForest(train,100);validationModel.means=modelStats(train).means;validationModel.stds=modelStats(train).stds;const vals=valid.map(r=>rawScore(r,validationModel)).sort((a,b)=>a-b);const threshold=vals[Math.min(vals.length-1,Math.floor(vals.length*.95))];const finalModel=buildForest(rows,100),stats=modelStats(rows);Object.assign(finalModel,stats,{threshold,validation:valid.length,validation95:threshold});return finalModel;}
function activateModel(rows,label){trainingRows=rows;forest=fitForest(rows);if($('modelState'))$('modelState').textContent=label.includes('synthetic')?'MODEL · DEMO':'MODEL · TRAINED';log('MODEL_TRAIN',`${label}: ${rows.length} rows, 100 trees, held-out threshold ${forest.threshold.toFixed(4)}`);}
function trainSynthetic(){const rows=Array.from({length:1000},synthRow);activateModel(rows,'synthetic 12-vital baseline');}
function parseCSV(text){const lines=text.trim().split(/\r?\n/);if(lines.length<51)throw Error('CSV needs a header and at least 50 data rows.');const headers=lines[0].split(',').map(x=>x.trim().toLowerCase());const idx=features.map(f=>headers.indexOf(f));if(idx.some(i=>i<0))throw Error('CSV must include all 12 columns: '+features.join(', '));const rows=[];for(let i=1;i<lines.length;i++){const c=lines[i].split(',');const row=idx.map(j=>Number(c[j]));if(row.length===12&&row.every(Number.isFinite))rows.push(row);}if(rows.length<50)throw Error('Could not parse at least 50 valid numeric rows.');return rows;}
function readVitals(){const ids=['v_hr','v_bp_sys','v_glucose','v_temp','v_sleep','v_stress','v_exercise','v_radiation','v_calcium','v_hydration','v_eye','v_cognitive'];const vals=ids.map(id=>Number($(id).value));const dia=Number($('v_bp_dia').value),radLimit=Number($('radAlertLimit').value);if(vals.some(v=>!Number.isFinite(v))||!Number.isFinite(dia)||!Number.isFinite(radLimit))throw Error('Fill every vital with a valid number.');const ranges=[[25,240],[50,260],[20,600],[30,43],[0,24],[0,10],[0,600],[0,100],[0,2000],[0,10],[0,100],[80,3000]];for(let i=0;i<vals.length;i++)if(vals[i]<ranges[i][0]||vals[i]>ranges[i][1])throw Error(`Value outside allowed input range for ${features[i]}.`);if(dia<30||dia>160||radLimit<=0||radLimit>100||vals[1]<=dia)throw Error('Check blood pressure: systolic must be higher than diastolic. Also verify the radiation review trigger.');return {row:vals,diastolic:dia,radLimit,note:$('vitalNote').value.trim()};}
