const [hr,bps,glu,temp,sleep,stress,exercise,rad,calcium,hydration,eye,cog]=x, bpd=v.diastolic;
if(hr<45||hr>130)add('Heart rate','CRITICAL',`Heart rate ${hr} bpm is outside the prototype review band.`,`Repeat the reading after a short rest if safe; check sensor placement and symptoms. Notify the crew medical officer promptly; use emergency protocol for symptoms.`);else if(hr<55||hr>110)add('Heart rate','REVIEW',`Heart rate ${hr} bpm is outside the routine screening band.`,`Repeat with a verified sensor and compare with the crew member's personal baseline. Log context (exercise, sleep, stress); notify medical officer if persistent.`);
