if(glu<54||glu>250)add('Blood sugar','CRITICAL',`Blood glucose ${glu} mg/dL crosses a high-priority prototype screen.`,`Verify with the approved device and check for symptoms. Contact the designated medical officer immediately; follow the crew medical protocol—do not self-adjust medication from this alert.`);else if(glu<70||glu>180)add('Blood sugar','REVIEW',`Blood glucose ${glu} mg/dL is outside the routine prototype screen.`,`Repeat/confirm using the approved device and log meal timing and activity. Share persistent readings with the medical officer.`);
if(temp<35.5||temp>=38)add('Body temperature','CRITICAL',`Temperature ${temp.toFixed(1)} °C crosses a high-priority prototype screen.`,`Confirm with the approved thermometer and check for symptoms/environmental causes. Notify the medical officer promptly; follow mission medical protocol.`);else if(temp<36||temp>=37.5)add('Body temperature','REVIEW',`Temperature ${temp.toFixed(1)} °C is outside the routine prototype screen.`,`Repeat with the approved thermometer after a short interval; log measurement method and symptoms. Escalate if persistent.`);
if(sleep<4)add('Sleep','CRITICAL',`Sleep ${sleep} h in the last 24 h indicates severe sleep shortfall for this prototype screen.`,`Review recent sleep log, workload and schedule. Notify crew health support; use approved rest/scheduling countermeasures.`);else if(sleep<6)add('Sleep','REVIEW',`Sleep ${sleep} h in the last 24 h is below the prototype review target.`,`Log sleep opportunity and disruptions; review workload and circadian schedule with crew support. Recheck next cycle.`);
if(stress>=8)add('Mood & stress','REVIEW',`Self-reported stress ${stress}/10 is high.`,`Offer a private crew check-in; record the crew member's preferred support. Contact behavioral-health support according to mission protocol if requested or persistent.`);
if(exercise<15)add('Exercise','REVIEW',`Exercise ${exercise} min in the last 24 h is low relative to this prototype's activity prompt.`,`Check equipment availability, schedule and symptoms. Review the approved individualized exercise plan with the crew health officer; do not force exercise when unwell.`);else if(exercise>180)add('Exercise','REVIEW',`Exercise ${exercise} min in the last 24 h is unusually high for this prototype prompt.`,`Verify activity log and recovery context; review workload/recovery with crew support.`);
if(rad>v.radLimit)add('Space radiation','CRITICAL',`Recorded radiation ${rad} mSv/day exceeds the mission-configured review trigger ${v.radLimit} mSv/day.`,`Verify dosimeter, units, time window and cumulative mission dose. Notify the radiation/flight operations officer and follow the mission radiation protection procedure. This trigger is user-configured, not a NASA exposure limit.`);
if(calcium>350)add('Urine calcium','REVIEW',`Urine calcium ${calcium} mg/24 h is above this prototype trend-review trigger.`,`Confirm collection duration and lab units; compare with the crew member's clinical baseline and hydration/activity context. Refer to the medical officer—no treatment is inferred.`);
if(hydration<1.2)add('Hydration','REVIEW',`Recorded fluid intake ${hydration} L/24 h is low for this prototype review prompt.`,`Verify the intake log and mission fluid accounting. Discuss with the medical officer, especially if symptoms or fluid restrictions apply; do not automatically increase fluids.`);else if(hydration>4.5)add('Hydration','REVIEW',`Recorded fluid intake ${hydration} L/24 h is unusually high for this prototype prompt.`,`Verify units and intake log; review with the medical officer, particularly if there are symptoms or fluid restrictions.`);
