function renderAlerts(items){const order={CRITICAL:0,REVIEW:1};items.sort((a,b)=>order[a.level]-order[b.level]);$('criticalCount').textContent=items.filter(x=>x.level==='CRITICAL').length;$('reviewCount').textContent=items.filter(x=>x.level==='REVIEW').length;$('normalCount').textContent=12-items.length;$('vitalOverall').textContent=items.some(x=>x.level==='CRITICAL')?'ACTION REQUIRED':items.length?'REVIEW NEEDED':'WITHIN SCREEN';$('vitalOverall').style.color=items.some(x=>x.level==='CRITICAL')?'var(--red)':items.length?'var(--amber)':'var(--green)';$('alertList').innerHTML=items.length?items.map((a,i)=>`<div class="event" style="grid-template-columns:105px 1fr"><span class="status ${a.level==='CRITICAL'?'high':'watch'}">${a.level}</span><div><b>${a.name}</b><p style="margin:5px 0;color:#d3e2f0">${a.reason}</p><p style="margin:0;color:#9fd6c6"><b>Recommended next step:</b> ${a.action}</p></div></div>`).join(''):'<div class="event"><time>ALL 12</time><span>No prototype screening rules were triggered. Continue routine monitoring and compare with personal baseline.</span><span class="status ok">WITHIN SCREEN</span></div>';}
function assessVitals(){try{const v=readVitals(),items=assessRules(v);lastVitalAssessment={timestamp:new Date().toISOString(),values:Object.fromEntries(features.map((f,i)=>[f,v.row[i]])),blood_pressure_diastolic:v.diastolic,radiation_review_trigger:v.radLimit,note:v.note,alerts:items};alertsAcknowledged=false;renderAlerts([...items]);updateSkeletonHealthMap(v);saveVitalHistory(v,items);log('VITAL_ASSESS',`${items.length} alert(s); ${items.filter(x=>x.level==='CRITICAL').length} critical; ${items.filter(x=>x.level==='REVIEW').length} review.`);return v;}catch(e){alert(e.message);throw e;}}
