// ---------- Mission scenario simulator ----------
let simRows=[];function runMission(){if(!forest){alert('The mission signal model is not ready. Reload the page and retry the simulation.');return;}const g=Number($('gravity').value),rad=Number($('radiation').value),ex=Number($('exercise').value),sl=Number($('sleep').value);if([g,rad,ex,sl].some(x=>!Number.isFinite(x))||g<0||g>2||rad<0||rad>100||ex<0||ex>10||sl<0||sl>12){alert('Check mission inputs; values are outside allowed ranges.');return;}const phase=$('phase').value;const rows=[];for(let i=0;i<30;i++){const fatigue=i/29;const hr=70+fatigue*(ex*1.8+rad*.18)+(0.16-g)*7+randn()*2.2;const sleep=Math.max(1,sl-fatigue*.9+randn()*.25);const reaction=280+fatigue*(9-ex*.25)*12+(7.5-sleep)*19+randn()*10;const exercise=Math.max(0,Math.min(10,ex+randn()*.25));const radiation=rad*(i+1)/30;rows.push([hr,118+randn()*9,95+randn()*10,36.8+randn()*.22,sleep,3+randn()*1.25,exercise*8,radiation,180+randn()*50,2.2+randn()*.3,92+randn()*4,reaction]);}simRows=rows;const scored=rows.map((r,i)=>({...scoreRow(r),step:i+1,input:r}));const peak=Math.max(...scored.map(x=>x.score));$('simSteps').textContent='30';$('peakAnomaly').textContent=peak.toFixed(3);$('phaseLabel').textContent=phase.replaceAll('_',' ');$('simState').textContent='Complete';$('missionState').textContent='MISSION SIM · COMPLETE';$('gravMetric').textContent=g.toFixed(2)+' g';$('radMetric').textContent=rad.toFixed(2)+' mSv/day';$('loadMetric').textContent=ex.toFixed(1)+'/10';drawChart(scored);const events=scored.filter(x=>x.score>forest.threshold).slice(0,8);$('missionEvents').innerHTML=events.length?events.map(x=>`<div class="event"><time>STEP ${x.step}</time><span>Baseline deviation · score ${x.score.toFixed(3)} · HR ${x.input[0].toFixed(0)} bpm · sleep ${x.input[4].toFixed(1)} h</span><span class="status ${x.score>Math.max(.65,forest.threshold*1.25)?'high':'watch'}">${x.score>Math.max(.65,forest.threshold*1.25)?'HIGH':'REVIEW'}</span></div>`).join(''):'<div class="event"><time>30 STEPS</time><span>No points exceeded the learned baseline threshold.</span><span class="status ok">WITHIN BASELINE</span></div>';log('MISSION_SIM',`${phase}; 30 steps; peak anomaly ${peak.toFixed(4)}; ${events.length} flagged steps.`);}
function drawChart(data){const c=$('missionChart'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#203750';ctx.lineWidth=1;for(let i=0;i<5;i++){let y=20+i*(h-40)/4;ctx.beginPath();ctx.moveTo(45,y);ctx.lineTo(w-15,y);ctx.stroke();}const max=Math.max(.5,...data.map(x=>x.score))*1.15;ctx.strokeStyle='#50d9ff';ctx.lineWidth=3;ctx.beginPath();data.forEach((x,i)=>{let px=45+(data.length===1?0:i*(w-65)/(data.length-1)),py=h-20-(x.score/max)*(h-40);if(!i)ctx.moveTo(px,py);else ctx.lineTo(px,py)});ctx.stroke();ctx.fillStyle='#8fa5c2';ctx.font='12px sans-serif';ctx.fillText('Anomaly score (relative)',48,15);ctx.fillText('Mission progression →',w-170,h-5);}
$('runMission').onclick=runMission;$('resetMission').onclick=()=>{$('gravity').value=.16;$('radiation').value=.35;$('exercise').value=5;$('sleep').value=7.5;$('missionEvents').innerHTML='<div class="event"><time>—</time><span>Scenario reset. Run simulation to generate events.</span><span class="status watch">IDLE</span></div>';$('missionState').textContent='MISSION SIM · READY';$('simSteps').textContent='0';$('peakAnomaly').textContent='—';$('simState').textContent='Ready';drawChart([]);log('MISSION_RESET','Mission scenario reset.');};
// ---------- MediaPipe face / iris tracking ----------
let mpCamera=null,faceMesh=null,eyeRunning=false,eyeAnim=0,faceFound=false,irisX=.5,irisY=.5,eyeFrames=0,eyeMatches=0,target={x:.5,y:.5,dx:.003,dy:.002};function resizeEyeCanvas(){const c=$('dotCanvas'),box=c.getBoundingClientRect();if(!box.width||!box.height)return;c.width=Math.round(box.width*devicePixelRatio);c.height=Math.round(box.height*devicePixelRatio);}
function eyeLoop(){if(!eyeRunning)return;const c=$('dotCanvas'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);target.x+=target.dx;target.y+=target.dy;if(target.x<.05||target.x>.95)target.dx*=-1;if(target.y<.08||target.y>.92)target.dy*=-1;ctx.fillStyle='#ffca68';ctx.shadowColor='#ffca68';ctx.shadowBlur=20;ctx.beginPath();ctx.arc(target.x*c.width,target.y*c.height,Math.max(8,c.width*.012),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;eyeFrames++;if(faceFound&&Math.hypot(target.x-irisX,target.y-irisY)<.22)eyeMatches++;$('gaze-hud').textContent=faceFound?`FACE TRACKED · PROXIMITY ${(100*eyeMatches/Math.max(1,eyeFrames)).toFixed(1)}%`:'NO FACE · MOVE INTO FRAME';$('faceDetection').textContent=faceFound?'Detected':'Not detected';$('irisPosition').textContent=faceFound?`${irisX.toFixed(2)}, ${irisY.toFixed(2)}`:'—';$('trackingFrames').textContent=eyeFrames;$('gazeProximity').textContent=faceFound?(100*eyeMatches/Math.max(1,eyeFrames)).toFixed(1)+'%':'—';eyeAnim=requestAnimationFrame(eyeLoop);}
async function startEye(){if(eyeRunning)return;if(!window.FaceMesh||!window.Camera){alert('MediaPipe libraries did not load. Check internet connection and reopen this file.');return;}try{resizeEyeCanvas();faceMesh=new FaceMesh({locateFile:f=>`https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/${f}`});faceMesh.setOptions({maxNumFaces:1,refineLandmarks:true,minDetectionConfidence:.5,minTrackingConfidence:.5});faceMesh.onResults(res=>{if(res.multiFaceLandmarks&&res.multiFaceLandmarks.length){faceFound=true;const lm=res.multiFaceLandmarks[0],a=lm[468]||lm[1],b=lm[473]||lm[1];irisX=1-(a.x+b.x)/2;irisY=(a.y+b.y)/2;}else faceFound=false;});const video=$('webcam-preview');mpCamera=new Camera(video,{onFrame:async()=>{if(eyeRunning)await faceMesh.send({image:video})},width:640,height:480});eyeRunning=true;eyeFrames=0;eyeMatches=0;await mpCamera.start();eyeLoop();log('CAMERA','MediaPipe face / iris tracking started.');}catch(e){eyeRunning=false;faceFound=false;log('CAMERA_ERROR',e.message);alert('Camera could not start: '+e.message+' Check camera permission and use localhost or HTTPS.');}}
function stopEye(){eyeRunning=false;cancelAnimationFrame(eyeAnim);if(mpCamera){mpCamera.stop();mpCamera=null;}faceFound=false;$('gaze-hud').textContent='CAMERA STOPPED';$('faceDetection').textContent='Stopped';log('CAMERA','Camera tracking stopped.');}$('startEye').onclick=startEye;$('stopEye').onclick=stopEye;window.addEventListener('resize',resizeEyeCanvas);
// ---------- Reaction-time test (not a game) ----------
let reactionState='idle',reactionStart=0,reactionTimer=null,reactionValues=[],falseStartCount=0;function updateReaction(){ $('lastReaction').textContent=reactionValues.length?reactionValues.at(-1)+' ms':'—';$('meanReaction').textContent=reactionValues.length?Math.round(reactionValues.reduce((a,b)=>a+b,0)/reactionValues.length)+' ms':'—';$('falseStarts').textContent=falseStartCount;$('trialCount').textContent=reactionValues.length;}
$('startReaction').onclick=()=>{clearTimeout(reactionTimer);reactionState='waiting';$('reactionDisplay').textContent='WAIT…';$('reactionDisplay').style.color='#ffca68';$('reactionHint').textContent='Wait for the cue. Respond only when it turns green.';reactionTimer=setTimeout(()=>{if(reactionState!=='waiting')return;reactionState='go';reactionStart=performance.now();$('reactionDisplay').textContent='RESPOND';$('reactionDisplay').style.color='#5ce0ae';},1200+Math.random()*2200);log('COGNITIVE','Reaction trial started.');};$('respondReaction').onclick=()=>{if(reactionState==='go'){const ms=Math.round(performance.now()-reactionStart);reactionValues.push(ms);reactionState='idle';$('reactionDisplay').textContent=ms+' ms';$('reactionDisplay').style.color='#50d9ff';$('reactionHint').textContent='Response recorded. Start another trial when ready.';updateReaction();log('COGNITIVE',`Valid reaction recorded: ${ms} ms`);}else if(reactionState==='waiting'){falseStartCount++;reactionState='idle';clearTimeout(reactionTimer);$('reactionDisplay').textContent='FALSE START';$('reactionDisplay').style.color='#ff6d7c';$('reactionHint').textContent='You responded before the cue. Trial cancelled.';updateReaction();log('COGNITIVE','False start recorded.');}else{$('reactionHint').textContent='No active trial. Start a new trial first.';}};$('resetReaction').onclick=()=>{clearTimeout(reactionTimer);reactionState='idle';reactionValues=[];falseStartCount=0;$('reactionDisplay').textContent='READY';$('reactionDisplay').style.color='var(--cyan)';$('reactionHint').textContent='Start a trial. Do not respond until the green cue appears.';updateReaction();log('COGNITIVE','Reaction test reset.');};
