function download(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}function report(){return {product:'AstroGuard Mission Digital Twin',generated_at:new Date().toISOString(),disclaimer:'Research prototype; not clinically validated or NASA endorsed.',model:forest?{algorithm:'12-feature Isolation Forest',trees:forest.trees.length,training_rows:forest.rows,validation_rows:forest.validation,threshold:forest.threshold}:null,vital_assessment:lastVitalAssessment,last_inference:lastInference,mission:{phase:$('phase').value,steps:simRows.length,peak_anomaly:simRows.length?Math.max(...simRows.map(r=>scoreRow(r).score)):null},camera:{frames:eyeFrames,face_detected:faceFound},reaction_test:{valid_trials:reactionValues,false_starts:falseStartCount,mean_ms:reactionValues.length?reactionValues.reduce((a,b)=>a+b,0)/reactionValues.length:null},events:logEntries,history:getVitalHistory(),long_mission:{days:longMissionRows.length,flagged_days:longMissionRows.filter(r=>forest&&r.score>forest.threshold).length},cabin_environment:{co2_mmHg:Number($('cabinCO2').value),o2_percent:Number($('cabinO2').value),pressure_kPa:Number($('cabinPressure').value),temperature_C:Number($('cabinTemp').value),humidity_percent:Number($('cabinHumidity').value),sensor_mode:$('cabinSensorMode').value},earth_link:{mode:'local simulation only',online:earthOnline,queued:earthQueued,delivered:earthDelivered}};}
