// ---------- Persistent historical trends (browser-local) ----------
const HISTORY_KEY='astroguard_vital_history_v1';
function getVitalHistory(){try{return JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]');}catch(e){return [];}}
function saveVitalHistory(v,items){
 const rows=getVitalHistory();
 rows.push({timestamp:new Date().toISOString(),values:[...v.row],diastolic:v.diastolic,note:v.note||'',alerts:items.map(a=>({name:a.name,level:a.level}))});
 try{localStorage.setItem(HISTORY_KEY,JSON.stringify(rows.slice(-1000)));}catch(e){log('HISTORY_STORAGE_ERROR','Browser storage is unavailable; this snapshot could not be persisted.');return;}
 renderVitalHistory();
}
function renderVitalHistory(){
 const rows=getVitalHistory(),count=$('historyCount');if(!count)return;
 count.textContent=rows.length;
 if(!rows.length){$('historyLatestHR').textContent='—';$('historyLatestBP').textContent='—';$('historyDirection').textContent='Waiting';$('historySummary').textContent='No saved records yet. Run an assessment to create the first snapshot.';$('historyList').innerHTML='';drawHistoryChart([]);return;}
 const latest=rows[rows.length-1],prev=rows.length>1?rows[rows.length-2]:null;
 $('historyLatestHR').textContent=latest.values[0]+' bpm';
 $('historyLatestBP').textContent=latest.values[1]+'/'+latest.diastolic;
 const delta=prev?latest.values[0]-prev.values[0]:0;
 $('historyDirection').textContent=!prev?'Baseline':delta>2?'HR ↑':delta< -2?'HR ↓':'HR stable';
 $('historySummary').textContent=prev?`Since previous saved assessment: heart rate ${delta>=0?'+':''}${delta.toFixed(1)} bpm; systolic BP ${(latest.values[1]-prev.values[1]>=0?'+':'')+(latest.values[1]-prev.values[1]).toFixed(1)} mmHg; ${latest.alerts.length} current alert(s). Records are stored only in this browser.`:'First snapshot saved. Save more assessments to compare trends over time.';
 $('historyList').innerHTML=rows.slice(-10).reverse().map(r=>`<div class="event"><time>${new Date(r.timestamp).toLocaleString()}</time><span>HR ${r.values[0]} bpm · BP ${r.values[1]}/${r.diastolic} · Sleep ${r.values[4]} h · Alerts ${r.alerts.length}</span><span class="status ${r.alerts.some(a=>a.level==='CRITICAL')?'high':r.alerts.length?'watch':'ok'}">${r.alerts.some(a=>a.level==='CRITICAL')?'PRIORITY':r.alerts.length?'REVIEW':'CLEAR'}</span></div>`).join('');
 drawHistoryChart(rows);
}
function drawHistoryChart(rows){
 const c=$('historyChart');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#203750';for(let i=0;i<5;i++){const y=20+i*(h-40)/4;ctx.beginPath();ctx.moveTo(45,y);ctx.lineTo(w-15,y);ctx.stroke();}
 if(!rows.length){ctx.fillStyle='#8fa5c2';ctx.font='14px sans-serif';ctx.fillText('Historical readings will appear here after assessments.',50,Math.round(h/2));return;}
 const vals=rows.slice(-40).map(r=>r.values[0]),min=Math.min(40,...vals),max=Math.max(120,...vals),span=Math.max(1,max-min);
 ctx.strokeStyle='#50d9ff';ctx.lineWidth=3;ctx.beginPath();vals.forEach((v,i)=>{const x=45+(vals.length===1?0:i*(w-65)/(vals.length-1)),y=h-22-(v-min)/span*(h-48);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();
 ctx.fillStyle='#8fa5c2';ctx.font='12px sans-serif';ctx.fillText('Heart rate · bpm · latest 40 saved assessments',48,15);
}
if($('exportHistory'))$('exportHistory').onclick=()=>{const rows=getVitalHistory();if(!rows.length){alert('No historical records to export.');return;}const header=['timestamp',...features,'diastolic','note','alert_count'];const csv=[header,...rows.map(r=>[r.timestamp,...r.values,r.diastolic,r.note,r.alerts.length])].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');download('astroguard_historical_vitals.csv',csv,'text/csv');};
if($('clearHistory'))$('clearHistory').onclick=()=>{if(confirm('Clear all saved historical vital records from this browser?')){localStorage.removeItem(HISTORY_KEY);renderVitalHistory();log('HISTORY','Historical vital records cleared by user.');}};

// ---------- Long-duration mission scenario ----------
let longMissionRows=[];
const MISSION_HISTORY_KEY='astroguard_mission_history_v1';
function getMissionHistory(){try{return JSON.parse(localStorage.getItem(MISSION_HISTORY_KEY)||'[]');}catch(e){return [];}}
function renderMissionHistory(){
 const el=$('missionHistory');if(!el)return;const rows=getMissionHistory();
 el.innerHTML=rows.length?rows.slice(-8).reverse().map(r=>`<div class="event"><time>${new Date(r.timestamp).toLocaleString()}</time><span>${r.days}-day ${r.phase} run · ${r.flagged_days} flagged days · peak deviation ${r.peak.toFixed(3)}</span><span class="status watch">SAVED</span></div>`).join(''):'<div class="event"><time>NO RECORDS</time><span>Completed long-duration simulations will be stored here.</span><span class="status watch">EMPTY</span></div>';
}
function saveMissionHistory(record){const rows=getMissionHistory();rows.push(record);try{localStorage.setItem(MISSION_HISTORY_KEY,JSON.stringify(rows.slice(-100)));}catch(e){log('MISSION_STORAGE_ERROR','Browser storage is unavailable; mission summary was not persisted.');}renderMissionHistory();}
function runLongMission(){
 if(!forest){alert('The research signal model is still initializing. Wait a moment and retry.');return;}
 const days=Number($('missionDurationDays').value),g=Number($('gravity').value),rad=Number($('radiation').value),ex=Number($('exercise').value),sl=Number($('sleep').value);
 if(!Number.isInteger(days)||days<1||days>365){alert('Mission duration must be a whole number from 1 to 365 days.');return;}
 if([g,rad,ex,sl].some(x=>!Number.isFinite(x))){alert('Check the mission environment inputs first.');return;}
 const phase=$('phase').value,rows=[];
 for(let d=1;d<=days;d++){
  const progress=d/days, cumulativeRad=rad*d;
  const microgravityFactor=Math.max(0,1-g/1.0);
  const hr=70+microgravityFactor*2+ex*.55+Math.min(12,cumulativeRad*.006)+Math.sin(d/9)*2+randn()*1.8;
  const sleep=Math.max(2,Math.min(10,sl-progress*.7+Math.sin(d/13)*.35+randn()*.18));
  const reaction=Math.max(160,280+(7.5-sleep)*18+progress*(phase==='transit'?18:8)+randn()*8);
  const row=[hr,118+randn()*5,76+randn()*4,36.8+randn()*.15,sleep,3+randn()*.5,ex*8,rad,180+randn()*25,2.2+randn()*.15,92+randn()*2,reaction];
  rows.push({day:d,row,score:scoreRow(row).score,cumulative_radiation_msv:cumulativeRad});
 }
 longMissionRows=rows;
 const peak=Math.max(...rows.map(r=>r.score)),flags=rows.filter(r=>r.score>forest.threshold);
 $('longDays').textContent=days;$('longFlags').textContent=flags.length;$('longPeak').textContent=peak.toFixed(3);$('longStatus').textContent='SIMULATED';
 $('simState').textContent=`${days}-day run complete`;$('simSteps').textContent=days;$('peakAnomaly').textContent=peak.toFixed(3);$('phaseLabel').textContent=phase.replaceAll('_',' ');
 drawChart(rows.map(r=>({score:r.score})));
 const selected=[...flags.slice(0,4),...flags.slice(-4)].filter((x,i,a)=>a.findIndex(y=>y.day===x.day)===i).slice(0,8);
 $('longMissionEvents').innerHTML=selected.length?selected.map(r=>`<div class="event"><time>DAY ${r.day}</time><span>Relative deviation ${r.score.toFixed(3)} · HR ${r.row[0].toFixed(0)} bpm · sleep ${r.row[4].toFixed(1)} h · cumulative scenario radiation ${r.cumulative_radiation_msv.toFixed(2)} mSv</span><span class="status ${r.score>Math.max(.65,forest.threshold*1.25)?'high':'watch'}">${r.score>Math.max(.65,forest.threshold*1.25)?'HIGH':'REVIEW'}</span></div>`).join(''):'<div class="event"><time>COMPLETE</time><span>No generated day exceeded the research model threshold.</span><span class="status ok">NO FLAGS</span></div>';
 saveMissionHistory({timestamp:new Date().toISOString(),days,phase,flagged_days:flags.length,peak});
 log('LONG_MISSION',`${days}-day ${phase} synthetic mission completed; ${flags.length} model flags; peak ${peak.toFixed(4)}.`);
}
if($('runLongMission'))$('runLongMission').onclick=runLongMission;

// ---------- Cabin environment monitoring ----------
let cabinSensorTimer=null;
function assessCabin(){
 const c={co2:Number($('cabinCO2').value),o2:Number($('cabinO2').value),pressure:Number($('cabinPressure').value),temp:Number($('cabinTemp').value),humidity:Number($('cabinHumidity').value)};
 if(Object.values(c).some(v=>!Number.isFinite(v))||c.co2<0||c.co2>100||c.o2<0||c.o2>100||c.pressure<=0||c.pressure>200||c.temp< -50||c.temp>80||c.humidity<0||c.humidity>100){alert('Check cabin readings; one or more values are outside the allowed input range.');return;}
 const alerts=[];
 if(c.co2>=3)alerts.push(['CO₂ elevated',`CO₂ ${c.co2} mmHg. Rising CO₂ can cause headache, breathlessness and impaired concentration; severe exposure can become dangerous. Verify sensor and follow vehicle-specific procedures.`,'high']);
 else if(c.co2>=1)alerts.push(['CO₂ trend watch',`CO₂ ${c.co2} mmHg. Recheck ventilation/scrubber status and trend; symptoms can include headache and reduced concentration.`,'watch']);
 if(c.o2<19.5)alerts.push(['O₂ low',`O₂ ${c.o2}%. Reduced oxygen availability can cause hypoxia, impaired judgement, confusion and loss of consciousness. Follow approved emergency procedures.`,'high']);
 else if(c.o2>23.5)alerts.push(['O₂ high',`O₂ ${c.o2}%. Oxygen-enriched atmospheres can increase fire risk; verify the reading against vehicle-specific limits.`,'watch']);
 if(c.pressure<70)alerts.push(['Cabin pressure low',`Pressure ${c.pressure} kPa. Low pressure can reduce oxygen partial pressure; rapid pressure loss is an emergency hazard.`,'high']);
 else if(c.pressure<80||c.pressure>110)alerts.push(['Pressure review',`Pressure ${c.pressure} kPa is outside this prototype's broad review band. Check trend and approved cabin limits.`,'watch']);
 if(c.temp>30)alerts.push(['Heat stress risk',`Temperature ${c.temp}°C. Heat can increase cardiovascular strain and dehydration and reduce performance.`,'watch']);
 else if(c.temp<16)alerts.push(['Cold environment',`Temperature ${c.temp}°C. Cold can impair dexterity and, with sufficient exposure, contribute to hypothermia.`,'watch']);
 if(c.humidity>70)alerts.push(['Humidity high',`Humidity ${c.humidity}%. High humidity reduces evaporative cooling and can promote condensation/microbial growth.`,'watch']);
 else if(c.humidity<20)alerts.push(['Humidity low',`Humidity ${c.humidity}%. Dry air may irritate eyes and airways and increase discomfort.`,'watch']);
 const status=alerts.some(a=>a[2]==='high')?'PRIORITY REVIEW':alerts.length?'REVIEW':'WITHIN PROTOTYPE BAND';
 $('cabinStatus').textContent=status;$('cabinStatus').style.color=alerts.some(a=>a[2]==='high')?'var(--red)':alerts.length?'var(--amber)':'var(--green)';
 $('cabinCO2Status').textContent=c.co2.toFixed(1)+' mmHg';$('cabinO2Status').textContent=c.o2.toFixed(1)+'%';$('cabinUpdated').textContent=new Date().toLocaleTimeString();
 $('cabinAlerts').innerHTML=alerts.length?alerts.map(a=>`<div class="event"><time>${a[0]}</time><span>${a[1]}</span><span class="status ${a[2]}">${a[2]==='high'?'PRIORITY':'REVIEW'}</span></div>`).join(''):'<div class="event"><time>OK</time><span>No prototype environmental review trigger crossed. Continue monitoring and use approved spacecraft limits.</span><span class="status ok">IN BAND</span></div>';
 $('hazardExplanations').innerHTML=[
  ['CO₂',c.co2>=1?`Current ${c.co2} mmHg: elevated CO₂ may cause headache, breathlessness and reduced concentration; high exposure can cause serious toxicity.`:'Current reading is not in the prototype review band. CO₂ buildup can cause headache, breathlessness and impaired concentration.'],
  ['O₂',c.o2<19.5?`Current ${c.o2}%: low oxygen availability can cause hypoxia, impaired judgement, confusion and loss of consciousness.`:`Current ${c.o2}%: maintain monitoring. Too little oxygen risks hypoxia; oxygen enrichment can increase fire risk.`],
  ['PRESSURE',c.pressure<80?`Current ${c.pressure} kPa: reduced pressure can lower oxygen partial pressure; rapid decompression can cause acute injury.`:`Current ${c.pressure} kPa: monitor stability. Pressure loss can impair oxygen delivery and rapid decompression is an acute hazard.`],
  ['TEMPERATURE',c.temp>30?`Current ${c.temp}°C: heat strain can increase cardiovascular load, dehydration and performance impairment.`:c.temp<16?`Current ${c.temp}°C: cold can reduce dexterity and severe/prolonged exposure can cause hypothermia.`:`Current ${c.temp}°C: monitor trends; heat and cold can both impair crew performance.`],
  ['HUMIDITY',c.humidity>70?`Current ${c.humidity}%: high humidity limits evaporative cooling and encourages condensation.`:c.humidity<20?`Current ${c.humidity}%: dry air can irritate eyes and airways.`:`Current ${c.humidity}%: monitor condensation and comfort trends.`]
 ].map(a=>`<div class="event"><time>${a[0]}</time><span>${a[1]}</span><span class="status watch">EFFECT</span></div>`).join('');
 log('CABIN_ASSESS',`${status}; CO2 ${c.co2} mmHg; O2 ${c.o2}%; pressure ${c.pressure} kPa; temperature ${c.temp} C; humidity ${c.humidity}%.`);
}
if($('assessCabin'))$('assessCabin').onclick=assessCabin;
function setCabinMode(){
 if(cabinSensorTimer){clearInterval(cabinSensorTimer);cabinSensorTimer=null;}
 if($('cabinSensorMode').value==='simulated'){
  cabinSensorTimer=setInterval(()=>{
   $('cabinCO2').value=Math.max(.2,Number($('cabinCO2').value)+(Math.random()-.48)*.08).toFixed(2);
   $('cabinO2').value=Math.max(18,Math.min(22,Number($('cabinO2').value)+(Math.random()-.5)*.12)).toFixed(2);
   $('cabinPressure').value=Math.max(95,Math.min(105,Number($('cabinPressure').value)+(Math.random()-.5)*.3)).toFixed(1);
   $('cabinTemp').value=Math.max(18,Math.min(28,Number($('cabinTemp').value)+(Math.random()-.5)*.3)).toFixed(1);
   $('cabinHumidity').value=Math.max(30,Math.min(60,Number($('cabinHumidity').value)+(Math.random()-.5)*1.2)).toFixed(0);
   assessCabin();
  },3000);
  log('CABIN_SENSOR','Synthetic cabin sensor stream enabled; values are simulated.');
 }else log('CABIN_SENSOR','Cabin sensor mode set to manual input.');
}
if($('cabinSensorMode'))$('cabinSensorMode').addEventListener('change',setCabinMode);

// ---------- Earth communications demonstration (not a real spacecraft link) ----------
let earthOnline=true,earthQueued=0,earthDelivered=0,earthQueue=[];
function earthEvent(title,message,status='watch'){const el=$('earthEvents');el.insertAdjacentHTML('afterbegin',`<div class="event"><time>${new Date().toLocaleTimeString()} · ${title}</time><span>${message}</span><span class="status ${status}">${status==='ok'?'DELIVERED':status==='high'?'OFFLINE':'SIMULATED'}</span></div>`);}
function updateEarthUI(){$('earthLinkState').textContent=earthOnline?'SIMULATED · LINK AVAILABLE':'SIMULATED · OFFLINE';$('earthLinkState').style.color=earthOnline?'var(--green)':'var(--red)';$('earthQueue').textContent=earthQueue.length;$('earthDelivered').textContent=earthDelivered;}
function deliverEarthPacket(packet){const delay=650+Math.floor(Math.random()*1400);setTimeout(()=>{earthDelivered++;$('earthLatency').textContent=delay+' ms (simulated)';updateEarthUI();earthEvent('DEMO DELIVERY',`Queued demo packet from ${new Date(packet.created_at).toLocaleTimeString()} acknowledged after ${delay} ms. No real Earth/spacecraft transmission occurred.`,'ok');log('EARTH_DEMO_DELIVERY','Local browser simulation acknowledged one packet; no real Earth connection.');},delay);}
if($('sendEarthPacket'))$('sendEarthPacket').onclick=()=>{
 const packet={created_at:new Date().toISOString(),source:'AstroGuard browser demo',vitals:(()=>{try{return readVitals().row;}catch(e){return null;}})(),cabin:{co2:Number($('cabinCO2').value),o2:Number($('cabinO2').value)},note:'Synthetic demo packet; not transmitted to Earth.'};
 if(!earthOnline){earthQueue.push(packet);updateEarthUI();earthEvent('PACKET QUEUED','Demo link is offline. Packet queued locally; no ground station received it.','high');log('EARTH_QUEUE','Demo telemetry packet queued locally during simulated outage.');return;}
 earthEvent('TRANSMITTING',`Demo packet ${packet.created_at} entered the local simulated link.`,'watch');deliverEarthPacket(packet);
};
if($('simulateEarthOutage'))$('simulateEarthOutage').onclick=()=>{earthOnline=false;updateEarthUI();earthEvent('LINK OUTAGE','Simulated outage enabled. New demo packets will queue locally.','high');log('EARTH_DEMO','Simulated communication outage.');};
if($('restoreEarthLink'))$('restoreEarthLink').onclick=()=>{earthOnline=true;const pending=earthQueue.splice(0);updateEarthUI();earthEvent('LINK RESTORED',`${pending.length} queued demo packet(s) released to the simulated link. No real network is connected.`,'ok');pending.forEach(deliverEarthPacket);log('EARTH_DEMO',`Simulated communication restored; ${pending.length} queued packet(s) released.`);};
function initNewModules(){renderVitalHistory();renderMissionHistory();updateEarthUI();assessCabin();}

// Boot
function boot(){
 try{makeTwin();}catch(e){if($('renderState'))$('renderState').textContent='3D VIEW UNAVAILABLE · CHECK INTERNET';log('TWIN_INIT_ERROR',e.message);}
 try{drawChart([]);}catch(e){log('CHART_INIT_ERROR',e.message);}
 try{updateReaction();}catch(e){log('REACTION_INIT_ERROR',e.message);}
 try{const initial=readVitals();updateSkeletonHealthMap(initial);}catch(e){log('VITAL_INIT_ERROR',e.message);}
 try{initNewModules();}catch(e){log('NEW_MODULE_INIT_ERROR',e.message);}
 log('BOOT','AstroGuard ready. Crew health screening and mission modules initialized.');
 setTimeout(()=>{try{trainSynthetic();}catch(e){log('MODEL_INIT_ERROR',e.message);}},50);
}window.addEventListener('load',boot);
